 void nav(){nav.removeAllViews();String[] labels={t("Главная","Home"),t("ТО","Service"),t("Финансы","Finance"),t("Авто","Auto"),t("Ещё","More")};String[] icons={"⌂","⚒","₽","◈","☰"};for(int i=0;i<labels.length;i++){final int p=i;LinearLayout item=new LinearLayout(this);item.setOrientation(LinearLayout.VERTICAL);item.setGravity(Gravity.CENTER);TextView ic=text(icons[i],20,true);ic.setGravity(Gravity.CENTER);ic.setTextColor(screen==p?blue:sub());TextView v=text(labels[i],10,screen==p);v.setGravity(Gravity.CENTER);v.setTextColor(screen==p?blue:sub());item.addView(ic,new LinearLayout.LayoutParams(-1,dp(30)));item.addView(v,new LinearLayout.LayoutParams(-1,dp(22)));if(screen==p)item.setBackground(glass(1));item.setOnClickListener(x->{screen=p;subPage=0;render();});nav.addView(item,new LinearLayout.LayoutParams(0,-1,1));}}
