 void setupAuto(EditText e,String hint){if(!(e instanceof AutoCompleteTextView))return;AutoCompleteTextView a=(AutoCompleteTextView)e;String[] base=suggestionValues(hint);ArrayAdapter<String> ad=new ArrayAdapter<String>(this,android.R.layout.simple_dropdown_item_1line,base){@Override public View getView(int p,View c,android.view.ViewGroup parent){TextView v=(TextView)super.getView(p,c,parent);v.setTextColor(fg());v.setTextSize(14);v.setPadding(dp(14),dp(12),dp(14),dp(12));v.setBackgroundColor(0xF00A1824);return v;}};a.setAdapter(ad);a.setThreshold(1);}
 String[] suggestionValues(String hint){String h=hint.toLowerCase(Locale.ROOT);if(h.contains("марка")||h.contains("brand"))return new String[]{"Volkswagen","BMW","Mercedes-Benz","Audi","Toyota","Lada","Kia","Hyundai","Skoda","Ford","Honda","Nissan","Mazda","Volvo","Porsche"};if(h.contains("модель")||h.contains("model")){String b=val("brand","").toLowerCase(Locale.ROOT);if(b.contains("volkswagen")||b.equals("vw"))return new String[]{"Polo","Golf","Passat","Tiguan","Touareg","Jetta"};if(b.contains("bmw"))return new String[]{"X1","X3","X5","X6","3 Series","5 Series"};if(b.contains("toyota"))return new String[]{"Camry","RAV4","Corolla","Land Cruiser"};if(b.contains("kia"))return new String[]{"Rio","Ceed","Sportage","K5","Sorento"};return new String[]{"Polo","Golf","X5","Camry","RAV4","Rio","Ceed","Octavia","Focus"};}if(h.contains("топливо")||h.contains("fuel"))return new String[]{"АИ-92","АИ-95","АИ-98","АИ-100","Дизель","Газ"};if(h.contains("короб")||h.contains("gear"))return new String[]{"АКПП","МКПП","CVT","DSG","AMT","AT"};if(h.contains("категор"))return new String[]{"ТО","Ремонт","Масло","Фильтры","Тормоза","Диагностика","Шины","Другое"};if(h.contains("сезон"))return new String[]{"Лето","Зима","Всесезон"};if(h.contains("статус"))return new String[]{"NEW","DIAGNOSIS","REPAIR","RESOLVED"};if(h.contains("станц")||h.contains("азс"))return dbSuggestions("fuel","station");if(h.contains("сервис")||h.contains("service center"))return dbSuggestions("service_center","name");if(h.contains("бренд")||h.contains("brand"))return dbSuggestions("part","brand");if(h.contains("поставщик")||h.contains("supplier"))return dbSuggestions("part","supplier");if(h.contains("название")||h.contains("title")){String[] a=dbSuggestions("service","title");String[] b=dbSuggestions("expense","title");ArrayList<String> z=new ArrayList<>();for(String v:a)z.add(v);for(String v:b)if(!z.contains(v))z.add(v);return z.toArray(new String[0]);}if(h.contains("артикул")||h.contains("part number"))return dbSuggestions("part","partNumber");return new String[0];}
 String[] dbSuggestions(String table,String column){ArrayList<String> out=new ArrayList<>();Cursor c=db.raw("SELECT DISTINCT "+column+" FROM "+table+" WHERE vehicleId=? AND "+column+"<>'' ORDER BY "+column+" LIMIT 30",new String[]{String.valueOf(active)});try{while(c.moveToNext())out.add(c.getString(0));}finally{c.close();}return out.toArray(new String[0]);}
 EditText input(String hint,String value){AutoCompleteTextView e=new AutoCompleteTextView(this);e.setHint(hint);e.setText(value);e.setTextColor(fg());e.setHintTextColor(sub());e.setTextSize(15);e.setSingleLine(true);e.setPadding(dp(14),0,dp(14),0);GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0x64182A38,0x32101B25});g.setCornerRadius(dp(15));g.setStroke(dp(1),0xB52AD2FF);e.setBackground(g);e.setDropDownBackgroundDrawable(new android.graphics.drawable.ColorDrawable(0xF0081722));e.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(50)){{setMargins(0,0,0,dp(8));}});setupAuto(e,hint);return e;}
 void header(String title,String subline){TextView h=text(title,27,true);add(h);if(subline!=null)add(small(subline));addGap(12);}
 void home(){if(active<0){showWelcome();return;}String vehicle=(val("brand","")+" "+val("model","")).trim();header("AUTO HUB",vehicle);LinearLayout hero=card();hero.setPadding(dp(18),dp(18),dp(18),dp(18));hero.addView(text(vehicle,24,true));hero.addView(small((val("year","").equals("0")?"":val("year","")+" · ")+val("engine","")+((val("gear","").isEmpty())?"":" · "+val("gear",""))));ImageView car=new ImageView(this);String carUri=val("photo","");if(carUri.isEmpty())car.setImageResource(carDrawableForVehicle());else try{String resolved=resolveAttachment(carUri);if(resolved.startsWith("/"))car.setImageURI(Uri.fromFile(new File(resolved)));else car.setImageURI(Uri.parse(resolved));}catch(Exception ignored){car.setImageResource(carDrawableForVehicle());}car.setAdjustViewBounds(true);car.setScaleType(ImageView.ScaleType.CENTER_INSIDE);hero.addView(car,new LinearLayout.LayoutParams(-1,dp(175)));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(text(fmt(num(val("mileage","0")))+" км",30,true),new LinearLayout.LayoutParams(0,dp(62),1));TextView status=text(healthText(),12,true);status.setTextColor(healthColor());status.setGravity(Gravity.CENTER);row.addView(status,new LinearLayout.LayoutParams(dp(118),dp(44)));hero.addView(row);add(hero);addGap(14);sectionTitle(t("Следующее ТО","Next service"));add(infoCard(nextService(),blue));addGap(12);sectionTitle(t("Быстрые действия","Quick actions"));LinearLayout q=new LinearLayout(this);q.setOrientation(LinearLayout.HORIZONTAL);String[] labels={"＋ ТО","＋ Заправка","＋ Расход","＋ Напоминание"};View.OnClickListener[] ls={v->serviceDialog(),v->fuelDialog(),v->expenseDialog(),v->reminderDialog()};for(int i=0;i<4;i++){Button b=btn(labels[i],blue);b.setTextSize(10);b.setOnClickListener(ls[i]);q.addView(b,new LinearLayout.LayoutParams(0,dp(54),1){{setMargins(dp(3),0,dp(3),0);}});}add(q);addGap(14);sectionTitle(t("Ключевые показатели","Key metrics"));LinearLayout m=new LinearLayout(this);m.setOrientation(LinearLayout.HORIZONTAL);m.addView(metric(t("Пробег","Mileage"),fmt(num(val("mileage","0"))),"км"),new LinearLayout.LayoutParams(0,dp(105),1));m.addView(metric(t("Расход","Consumption"),consumption(),"л/100 км"),new LinearLayout.LayoutParams(0,dp(105),1));m.addView(metric(t("Стоимость/км","Cost/km"),costKm(),"₽/км"),new LinearLayout.LayoutParams(0,dp(105),1));add(m);addGap(12);sectionTitle(t("Последняя активность","Recent activity"));activityCards(3);}
 View metric(String title,String value,String unit){LinearLayout c=card();c.setPadding(dp(11),dp(10),dp(11),dp(10));c.addView(small(title));TextView b=text(value,18,true);b.setPadding(0,dp(5),0,0);c.addView(b);c.addView(small(unit));return c;}
 View actionRow(String[] labels,View.OnClickListener[] ls){LinearLayout r=new LinearLayout(this);for(int i=0;i<3;i++){Button b=btn(labels[i],i==0?blue:(i==1?Color.rgb(0,177,145):Color.rgb(240,154,44)));b.setTextSize(11);b.setOnClickListener(ls[i]);r.addView(b,new LinearLayout.LayoutParams(0,dp(52),1){{setMargins(dp(3),dp(3),dp(3),dp(3));}});}return r;}
 int carDrawableForVehicle(){String b=val("brand","").toLowerCase(Locale.ROOT);String m=val("model","").toLowerCase(Locale.ROOT);String y=val("year","");if((b.contains("volkswagen")||b.contains("vw"))&&m.contains("polo"))return R.drawable.car_placeholder;if(b.contains("bmw")&&m.contains("x5"))return R.drawable.car_placeholder;return R.drawable.car_placeholder;}
 void sectionTitle(String s){TextView h=text(s,18,true);h.setPadding(0,dp(3),0,dp(6));add(h);}
 TextView infoCard(String s,int color){TextView v=text(s,13,true);v.setPadding(dp(16),dp(16),dp(16),dp(16));GradientDrawable g=glass(1);g.setStroke(dp(1),color);v.setBackground(g);return v;}
 void activityCards(int n){Cursor c=db.raw("SELECT kind,title,detail,date,time FROM activity WHERE vehicleId=? ORDER BY createdAt DESC LIMIT ?",new String[]{String.valueOf(active),String.valueOf(n)});try{while(c.moveToNext()){LinearLayout x=card();x.addView(text(c.getString(1),14,true));x.addView(small(c.getString(3)+" · "+c.getString(4)+" · "+c.getString(2)));x.addView(small(c.getString(3)));add(x);addGap(7);}}finally{c.close();}}
 String nextService(){Cursor c=db.raw("SELECT title,nextDate,nextMileage,mileage FROM service WHERE vehicleId=? AND (nextMileage>0 OR nextDate<>'') ORDER BY id DESC",new String[]{String.valueOf(active)});try{if(!c.moveToFirst())return t("Нет запланированного обслуживания","No planned service");String title=c.getString(0);double nk=c.getDouble(2);String nd=c.getString(1);if(nk>0)return title+" · "+fmt(nk)+" км";return title+" · "+nd;}finally{c.close();}}
 String healthText(){Cursor d=db.raw("SELECT expiryDate FROM document WHERE vehicleId=? AND expiryDate<>''",new String[]{String.valueOf(active)});try{while(d.moveToNext())if(d.getString(0).compareTo(today())<0)return t("КРИТИЧНО","CRITICAL");}finally{d.close();}Cursor svc=db.raw("SELECT nextMileage,nextDate FROM service WHERE vehicleId=?",new String[]{String.valueOf(active)});double currentKm=num(val("mileage","0"));try{while(svc.moveToNext()){double nk=svc.getDouble(0);String nd=svc.getString(1);if((nk>0&&currentKm>=nk)||(nd!=null&&!nd.isEmpty()&&nd.compareTo(today())<0))return t("ПРОСРОЧЕНО","OVERDUE");}}finally{svc.close();}Cursor r=db.raw("SELECT COUNT(*) FROM reminder WHERE vehicleId=? AND done=0 AND date<?",new String[]{String.valueOf(active),today()});try{if(r.moveToFirst()&&r.getInt(0)>0)return t("ПРОСРОЧЕНО","OVERDUE");}finally{r.close();}Cursor p=db.raw("SELECT COUNT(*) FROM issue WHERE vehicleId=? AND status IN ('NEW','DIAGNOSIS','REPAIR')",new String[]{String.valueOf(active)});try{if(p.moveToFirst()&&p.getInt(0)>0)return t("ВНИМАНИЕ","ATTENTION");}finally{p.close();}return t("НОРМА","NORMAL");}
 int healthColor(){String h=healthText();return h.contains("КРИТ")||h.equals("CRITICAL")?Color.rgb(255,74,88):(h.contains("ПРОС")||h.equals("OVERDUE")||h.contains("ВНИМ")||h.equals("ATTENTION")?Color.rgb(255,171,58):Color.rgb(40,207,147));}
 double sumPeriod(String table,String col){if(periodDays<=0)return sum(table,col);String since=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date(System.currentTimeMillis()-periodDays*86400000L));Cursor c=db.raw("SELECT COALESCE(SUM("+col+"),0) FROM "+table+" WHERE vehicleId=? AND date>=?",new String[]{String.valueOf(active),since});try{return c.moveToFirst()?c.getDouble(0):0;}finally{c.close();}}
double totalExpenses(){return sum("expense","amount")+sum("fuel","total")+sum("service","cost");}
 double sum(String table,String col){Cursor c=db.raw("SELECT COALESCE(SUM("+col+"),0) FROM "+table+" WHERE vehicleId=?",new String[]{String.valueOf(active)});try{return c.moveToFirst()?c.getDouble(0):0;}finally{c.close();}}
 String money(double x){return x<0?t("Некорректно","Invalid"):String.format(Locale.getDefault(),"%.0f",x);}
 String consumption(){Cursor c=db.raw("SELECT mileage,liters,fullTank FROM fuel WHERE vehicleId=? ORDER BY mileage,id",new String[]{String.valueOf(active)});double anchorKm=-1,fuelSince=0,totalLit=0,totalDist=0;try{while(c.moveToNext()){double km=c.getDouble(0),l=c.getDouble(1);boolean full=c.getInt(2)!=0;if(km<0||l<0)continue;if(full){if(anchorKm>=0&&km>anchorKm){totalDist+=km-anchorKm;totalLit+=fuelSince+l;}anchorKm=km;fuelSince=0;}else if(anchorKm>=0){fuelSince+=l;}}}finally{c.close();}return totalDist<=0?t("Недостаточно данных","Not enough data"):String.format(Locale.getDefault(),"%.1f",CarMath.consumption(totalLit,totalDist));}
 String costKm(){double dist=distance();return dist<=0?t("Недостаточно данных","Not enough data"):String.format(Locale.getDefault(),"%.2f",CarMath.costPerKm(totalExpenses(),dist));}
 double distance(){Cursor c=db.raw("SELECT MIN(mileage),MAX(mileage) FROM (SELECT mileage FROM fuel WHERE vehicleId=? UNION ALL SELECT mileage FROM service WHERE vehicleId=? UNION ALL SELECT mileage FROM expense WHERE vehicleId=?)",new String[]{String.valueOf(active),String.valueOf(active),String.valueOf(active)});try{if(!c.moveToFirst())return 0;double a=c.getDouble(0),b=c.getDouble(1);return b>a?b-a:0;}finally{c.close();}}
 String fmt(double n){return String.format(Locale.getDefault(),"%.0f",n);}
 void advanceMileage(double km){if(km<=0)return;double cur=num(val("mileage","0"));if(km>cur){ContentValues v=new ContentValues();v.put("mileage",km);db.update("vehicle",v,"id=?",new String[]{String.valueOf(active)});}}
 boolean validDate(String s, boolean allowEmpty){if(s==null||s.trim().isEmpty())return allowEmpty;try{SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setLenient(false);f.parse(s.trim());return true;}catch(Exception e){return false;}}
boolean validNonNegative(double x){return !Double.isNaN(x)&&!Double.isInfinite(x)&&x>=0;}
String attachment(){String a=pendingAttachment;if(a==null||a.isEmpty())a=getPreferences(0).getString("pending_attachment","");pendingAttachment="";getPreferences(0).edit().remove("pending_attachment").apply();return a;}
void warnMileageIfLower(double km,Runnable save){double cur=num(val("mileage","0"));if(km<0||Double.isNaN(km)){toast(t("Некорректный пробег","Invalid mileage"));return;}if(km<cur){new AlertDialog.Builder(this).setTitle(t("Пробег меньше текущего","Mileage is lower than current")) .setMessage(t("Сохранить меньший пробег для этой записи? Текущий пробег автомобиля не будет уменьшен автоматически.","Save this lower mileage for the record? The vehicle's current mileage will not be lowered automatically.")) .setNegativeButton(t("Отмена","Cancel"),null).setPositiveButton(t("Сохранить","Save"),(d,w)->save.run()).show();}else save.run();}
void serviceScreen(){header(t("Обслуживание","Service"),t("История, работы, детали и план","History, work, parts and plan"));Button add=btn(t("＋ Добавить обслуживание","＋ Add service"),blue);add.setOnClickListener(v->serviceDialog());add(add);addGap(10);EditText q=input(t("Поиск по работам, сервисам и деталям…","Search service, work and parts…"),"");add(q);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);add(list);Runnable run=()->{list.removeAllViews();String needle=q.getText().toString().trim().toLowerCase(Locale.ROOT);Cursor c=db.all("service",active);try{if(!c.moveToFirst()){empty(t("Обслуживание ещё не добавлено","No service records yet"),this::serviceDialog);return;}do{long id=c.getLong(0);String title=c.getString(c.getColumnIndexOrThrow("title"));String cat=c.getString(c.getColumnIndexOrThrow("category"));String desc=c.getString(c.getColumnIndexOrThrow("description"));String all=(title+" "+cat+" "+desc+" "+c.getString(c.getColumnIndexOrThrow("center"))).toLowerCase(Locale.ROOT);if(!needle.isEmpty()&&!all.contains(needle))continue;LinearLayout x=card();x.addView(text(title,17,true));x.addView(small(c.getString(c.getColumnIndexOrThrow("date"))+" · "+fmt(c.getDouble(c.getColumnIndexOrThrow("mileage")))+" км"));x.addView(small(cat+" · "+money(c.getDouble(c.getColumnIndexOrThrow("cost")))+" ₽"));if(desc!=null&&!desc.isEmpty())x.addView(small(desc));String center=c.getString(c.getColumnIndexOrThrow("center"));if(center!=null&&!center.isEmpty())x.addView(small(t("Сервис: ","Service: ")+center));Cursor pc=db.raw("SELECT name,brand,partNumber,quantity,price FROM part WHERE vehicleId=? AND serviceId=? ORDER BY id DESC",new String[]{String.valueOf(active),String.valueOf(id)});try{while(pc.moveToNext())x.addView(small("• "+pc.getString(0)+" · "+pc.getString(1)+" · "+pc.getString(2)+" · "+fmt(pc.getDouble(3))+" шт · "+money(pc.getDouble(4))+" ₽"));}finally{pc.close();}LinearLayout actions=new LinearLayout(this);Button edit=btn(t("Изменить","Edit"),blue);edit.setOnClickListener(v->serviceDialog(id));Button part=btn(t("＋ Деталь","＋ Part"),blue);part.setOnClickListener(v->partDialog(-1,id));actions.addView(edit,new LinearLayout.LayoutParams(0,dp(48),1));actions.addView(part,new LinearLayout.LayoutParams(0,dp(48),1));x.addView(actions);add(x);addGap(8);}while(c.moveToNext());}finally{c.close();}};q.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){run.run();}public void afterTextChanged(Editable e){}});run.run();}
