 void fuelDialog(){fuelDialog(-1);}void fuelDialog(long id){final LinearLayout l=form();JSONObject o=new JSONObject();Cursor old=id>0?db.raw("SELECT * FROM fuel WHERE id=?",new String[]{String.valueOf(id)}):null;o=row(old);if(old!=null)old.close();EditText date=input("Дата YYYY-MM-DD",o.optString("date",today())),km=input("Пробег, км",fmt(o.optDouble("mileage",num(val("mileage","0"))))),lit=input("Литры",fmt(o.optDouble("liters",0))),price=input("Цена за литр, ₽",fmt(o.optDouble("price",0))),type=input("Тип топлива",o.optString("type","АИ-95")),station=input("АЗС",o.optString("station","")),full=input("Полный бак: 1 = да, 0 = нет",o.optInt("fullTank",1)+"");for(EditText e:new EditText[]{date,km,lit,price,type,station,full})l.addView(e);Button save=btn("Сохранить",blue);l.addView(save);if(id>0){Button del=btn("Удалить",Color.RED);l.addView(del);del.setOnClickListener(v->confirmDelete("fuel",id));}addDialogCard("Заправка",l);save.setOnClickListener(v->{double L=num(lit.getText().toString()),P=num(price.getText().toString()),K=num(km.getText().toString());if(L<=0||P<0){toast("Введите корректные литры и цену");return;}ContentValues x=new ContentValues();x.put("vehicleId",active);x.put("date",date.getText().toString());x.put("mileage",K);x.put("liters",L);x.put("price",P);x.put("total",CarMath.total(L,P));x.put("type",type.getText().toString());x.put("station",station.getText().toString());x.put("fullTank",(int)num(full.getText().toString()));if(id>0)db.update("fuel",x,"id=?",new String[]{String.valueOf(id)});else{db.insert("fuel",x);db.log(active,"ЗАПРАВКА",type.getText().toString(),String.format(Locale.getDefault(),"%.1f л · %.0f ₽",L,L*P));}advanceMileage(K);render();});}
