 void documentScreen(){header("Документы", "Сроки действия и файлы");Button a=btn("+ Добавить документ",blue);a.setOnClickListener(v->documentDialog());add(a);addGap(10);Cursor c=db.all("document",active);try{if(!c.moveToFirst()){empty("Документы ещё не добавлены",this::documentDialog);return;}do{long id=c.getLong(0);LinearLayout x=card();String exp=c.getString(c.getColumnIndexOrThrow("expiryDate"));String state=exp.isEmpty()?"Без срока":(exp.compareTo(today())<0?"ИСТЁК":(exp.equals(today())?"СЕГОДНЯ":exp));TextView h=text(c.getString(c.getColumnIndexOrThrow("title")),14,true);h.setTextColor(exp.compareTo(today())<0&&!exp.isEmpty()?Color.rgb(255,74,88):fg());x.addView(h);x.addView(small(c.getString(c.getColumnIndexOrThrow("type"))+" · "+state));Button e=btn("Изменить",blue);e.setOnClickListener(v->documentDialog(id));x.addView(e);add(x);addGap(7);}while(c.moveToNext());}finally{c.close();}}
